<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {api,newKey,authGeneration} from '../api'
import {cacheGet,cacheSet,accountId,backendBase} from '../platform/bridge'
import ServerSelectionWriting from './ServerSelectionWriting.vue'
import type {SelectionEditScope,SelectionEditResult} from '../api/selection-edits'
const props=defineProps<{scope:SelectionEditScope;offline?:boolean}>(),emit=defineEmits<{saved:[result:SelectionEditResult];busy:[value:boolean]}>(),text=ref(props.scope.originalText),loading=ref(true),saving=ref(false),error=ref(''),saved=ref(true),cacheError=ref(false),loadError=ref(false)
const writingBusy=ref(false),writer=ref<{flush:()=>Promise<void>}|null>(null)
watch(writingBusy,value=>emit('busy',value||saving.value))
const frozen=JSON.parse(JSON.stringify(props.scope)) as SelectionEditScope,auth=authGeneration(),draftKey='selection-draft:'+frozen.branchId+':'+frozen.revisionId+':'+frozen.startAnchor.blockId+':'+frozen.startAnchor.start+':'+frozen.endAnchor.end+(frozen.startAnchor.blockId===frozen.endAnchor.blockId?'':':to:'+frozen.endAnchor.blockId)
const keys=new Map<string,string>(),owner=accountId(),base=backendBase();let disposed=false,hydrating=true,work=Promise.resolve(),generation=0
const active=()=>!disposed&&auth===authGeneration()&&owner===accountId()&&base===backendBase()
function persist(){if(hydrating||!active())return work;const value={bookId:frozen.bookId,branchId:frozen.branchId,revisionId:frozen.revisionId,startAnchor:frozen.startAnchor,endAnchor:frozen.endAnchor,text:text.value,intents:[...keys].slice(-20)},token=++generation;saved.value=false;work=work.catch(()=>{}).then(async()=>{if(!active())return;await cacheSet(draftKey,value);if(active()&&token===generation){saved.value=true;cacheError.value=false}});void work.catch(e=>{if(active()&&token===generation){error.value=(e as Error).message;cacheError.value=true}});return work}
async function retryDraft(){if(!active()||loading.value||saving.value)return;error.value='';try{await persist()}catch{/* persist exposes the current durable-cache failure */}}
watch(text,()=>void persist())
async function flush(){await work;if(!saved.value)throw new Error('输入尚未保存，请保留当前文字后重试')}
async function apply(){if(props.offline||saving.value||writingBusy.value||loading.value||!active())return;saving.value=true;emit('busy',true);error.value='';try{await persist();await flush();if(!active())return;const body={startAnchor:frozen.startAnchor,endAnchor:frozen.endAnchor,replacementText:text.value,expectedSourceHeadRevisionId:frozen.headRevisionId,sourcePolicy:frozen.revisionId===frozen.headRevisionId?'requireUnchanged':'forkPinned'},signature=JSON.stringify(body),key=keys.get(signature)||newKey();keys.set(signature,key);await persist();await flush();if(!active())return;const result=await api<SelectionEditResult>('/books/'+frozen.bookId+'/selection-edits',{method:'POST',body,key});if(active()){saving.value=false;emit('busy',false);emit('saved',result)}}catch(e){if(active())error.value=(e as Error).message}finally{if(active()){saving.value=false;emit('busy',false)}}}
onBeforeRouteLeave(async()=>{if(saving.value||writingBusy.value)return false;try{await flush();await writer.value?.flush();return true}catch(e){error.value=(e as Error).message;return false}})
async function loadDraft(){if(!active())return;loading.value=true;hydrating=true;loadError.value=false;try{const draft=await cacheGet<{text:string;intents?:[string,string][]}>(draftKey);if(!active())return;if(draft){if(typeof draft.text!=='string'||draft.text.length>1_000_000||draft.intents!==undefined&&!Array.isArray(draft.intents))throw new Error('草稿记录无法读取，原输入保留');text.value=draft.text;for(const pair of (draft.intents||[]).slice(-20)){if(!Array.isArray(pair)||typeof pair[0]!=='string'||typeof pair[1]!=='string'||pair[1].length>160)throw new Error('草稿请求记录无法校验，原输入保留');keys.set(pair[0],pair[1])}}await nextTick();if(active()){hydrating=false;loading.value=false;error.value=''}}catch(e){if(active()){error.value=(e as Error).message;loadError.value=true}}}
onMounted(()=>void loadDraft())
onUnmounted(()=>{disposed=true;generation++})
defineExpose({flush:async()=>{await flush();await writer.value?.flush()}})
</script>
<template><form class="selection-editor" @submit.prevent="apply"><details><summary>原选区</summary><blockquote>{{scope.originalText||'插入位置'}}</blockquote></details><label>新的文字<textarea v-model="text" :disabled="loading||saving||writingBusy" rows="10" maxlength="1000000"/></label><div class="selection-editor-actions"><small role="status">{{loading?'正在打开…':saved?'输入已保存':'正在保存输入…'}}</small><button class="primary" :disabled="offline||loading||saving||writingBusy||!saved">{{saving?'正在保存修订…':scope.revisionId===scope.headRevisionId?'保存到新故事线':'从旧版本另开故事线'}}</button></div><p v-if="error" role="alert" class="error">{{error}}</p><button v-if="loadError" type="button" @click="loadDraft">重试读取草稿</button><button v-if="cacheError&&!saved" type="button" :disabled="loading||saving||writingBusy" @click="retryDraft">重试保存输入</button><ServerSelectionWriting v-if="!loading" ref="writer" :scope="scope" :disabled="saving" :offline="offline" @busy="writingBusy=$event" @saved="emit('saved',$event)"/></form></template>
<style scoped>.selection-editor{display:grid;gap:24px}.selection-editor label{display:grid;gap:12px}.selection-editor textarea{min-height:240px;resize:vertical;font:17px/1.75 var(--font-serif,serif)}.selection-editor blockquote{white-space:pre-wrap;overflow-wrap:anywhere;margin:16px 0;color:var(--muted);font-size:15px;line-height:1.8}.selection-editor-actions{display:flex;gap:16px;justify-content:space-between;align-items:center;flex-wrap:wrap}.selection-editor-actions small{color:var(--muted)}.selection-editor summary{cursor:pointer;min-height:44px;display:flex;align-items:center}</style>
